import requestsfrom bs4 import BeautifulSoupimport osimport urllib.parse# Function to download a file from a URLdef download_file(url, folder_path):    if not os.path.exists(folder_path):        os.makedirs(folder_path)    response = requests.get(url)    if response.status_code == 200:        file_name = os.path.join(folder_path, url.split('/')[-1])        with open(file_name, 'wb') as file:            file.write(response.content)        print(f"Downloaded: {file_name}")    else:        print(f"Failed to download: {url}")# List of URLs of the websites to scrapewebsite_urls = [    'https://www.bargehibernia.com/',    'https://www.bargehibernia.com/mainpage/history',    'https://www.bargehibernia.com/mainpage/originalphotos',    'https://www.bargehibernia.com/mainpage/interiorconstruction',    'https://www.bargehibernia.com/mainpage/architectsdrawings',    'https://www.bargehibernia.com/mainpage/conditionsurveyreport',    # Add more URLs as needed]# Loop over each website URLfor website_url in website_urls:    # Send a request to fetch the website content    response = requests.get(website_url)    if response.status_code == 200:        soup = BeautifulSoup(response.content, 'html.parser')                # Find all image and video tags        media_tags = soup.find_all(['img', 'video'])                # Extract the src attribute from each media tag        media_urls = [media['src'] for media in media_tags if 'src' in media.attrs]                # Download each media file        for media_url in media_urls:            # Handle relative URLs            if media_url.startswith('/'):                media_url = urllib.parse.urljoin(website_url, media_url)            download_file(media_url, 'downloaded_media')    else:        print(f"Failed to retrieve the website. Status code: {response.status_code}")